/// 诊断域的文字。按语言取实现。
pub fn diagnostics(language: AppLanguage) -> &'static dyn DiagnosticsStrings {
    match language {
        AppLanguage::En => &DiagnosticsStringsEn,
        AppLanguage::Zh => &DiagnosticsStringsZh,
        AppLanguage::Ru => &DiagnosticsStringsRu,
        AppLanguage::Ja => &DiagnosticsStringsJa,
        AppLanguage::Ko => &DiagnosticsStringsKo,
        AppLanguage::Fr => &DiagnosticsStringsFr,
        AppLanguage::De => &DiagnosticsStringsDe,
        AppLanguage::Es => &DiagnosticsStringsEs,
    }
}
